/// Plugin POS management (e-commerce plugins). V2 signature only.
#[derive(Debug, Clone, Copy)]
pub struct Plugin<'a> {
    client: &'a Client,
}

impl<'a> Plugin<'a> {
    /// Banks the merchant can add, with each bank's credential fields. `GET /merchant/v1/plugin/banks` Auth: Signed (V2 only).
    pub async fn list_banks(&self) -> Result<Value> {
        self.client
            .request(Method::GET, "/merchant/v1/plugin/banks", None, &[])
            .await
    }

    /// The merchant's ACTIVE and PASSIVE POSes (secrets masked). `GET /merchant/v1/plugin/poses` Auth: Signed (V2 only).
    pub async fn list_poses(&self) -> Result<Value> {
        self.client
            .request(Method::GET, "/merchant/v1/plugin/poses", None, &[])
            .await
    }

    /// Add a bank POS (body: alias, name, credentials). `POST /merchant/v1/plugin/poses` Auth: Signed (V2 only).
    pub async fn create_pos(&self, body: &(impl Serialize + ?Sized)) -> Result<Value> {
        self.client
            .request(
                Method::POST,
                "/merchant/v1/plugin/poses",
                Some(serde_json::to_value(body)?),
                &[],
            )
            .await
    }

    /// Update a POS's credentials; blank, null or the mask keeps a stored secret. `PATCH /merchant/v1/plugin/poses/{pos_id}/credentials` Auth: Signed (V2 only).
    pub async fn update_pos_credentials(
        &self,
        pos_id: impl Display,
        body: &(impl Serialize + ?Sized),
    ) -> Result<Value> {
        self.client
            .request(
                Method::PATCH,
                &format!(
                    "/merchant/v1/plugin/poses/{}/credentials",
                    path_param(pos_id)?
                ),
                Some(serde_json::to_value(body)?),
                &[],
            )
            .await
    }
}
